// === Tab: Intersection1 ===
let NB_MAX = 200;
let NB_MIN = 4;
let NB = int(random)(NB_MIN, NB_MAX);
let ligne=false;
let back=true;
let doublets;

function setup()
{ 
  stroke(0, 120);
  createCanvas(windowWidth, windowHeight, WEBGL);
  doublets = new Array(NB_MAX);
  reset();
}

function reset()
{
  for (i = 0; i < NB_MAX; i ++)
  {
    doublets[i] = new Doublet(new PVector(random(width), random(height)), new PVector(random(width), random(height)));
  }
}

function draw()
{
  if( back ) background(0);
  for (i = 0; i < NB; i ++)
  {
    doublets[i].update();
  }
  //check intersection between each doublets pair
  for (i = 0; i < NB; i ++)
  {
    for (j = i+1; j < NB; j ++)
    {
      doublets[i].checkIntersection(doublets[j]);
    }
  }
}

function mouseClicked()
{
  reset();
}

function keyPressed()
{
  if (key == 'w')
  {
    NB = constrain(NB += 4, NB_MIN, NB_MAX);
  } else if (key == 'q')
  {
    NB = constrain(NB -= 4, NB_MIN, NB_MAX);
  } else if (key == 'l')
  {
    ligne=!ligne;
  } else if (key == 'b')
  {
    back=!back;
  }
}

class Doublet
{
  A, B;
  let col = color(random(255), random(255), random(255));

  constructor(p_A, p_B)
  {
    A = new Extremity(p_A);
    B = new Extremity(p_B);
  }

  function update()
  {
    A.update();
    B.update();
		if(ligne){
			stroke(255);
    	line(A.x, A.y, B.x, B.y);
    	fill(0);
    	ellipse(A.x, A.y, 3, 3);
    	ellipse(B.x, B.y, 3, 3);
		}
  }

  function checkIntersection(p_d)
  {
    let C = p_d.A.get();
    let D = p_d.B.get();
    let a1 = (B.y - A.y) / (B.x - A.x);//let slope
    let a2 = (D.y - C.y) / (D.x - C.x);//let slope
    if (a1 != a2)//segments are not parallel
    {
      let b1 = A.y - A.x * (B.y - A.y) / (B.x - A.x);
      let b2 = C.y - C.x * (D.y - C.y) / (D.x - C.x);
      let xo = (b2 - b1) / (a1 - a2);
      let yo = b1 + a1 * (b2 - b1) / (a1 - a2);
      if ((A.x < B.x ? A.x <= xo && xo <= B.x : B.x <= xo && xo <= A.x)
        && (A.y < B.y ? A.y <= yo && yo <= B.y : B.y <= yo && yo <= A.y)
        && (C.x < D.x ? C.x <= xo && xo <= D.x : D.x <= xo && xo <= C.x)
        && (C.y < D.y ? C.y <= yo && yo <= D.y : D.y <= yo && yo <= C.y))
      {
        fill((col + p_d.col) / 2);
        ellipse(xo, yo, 10, 10);
      }
    }
  }
}

class Extremity
{
  x, y, sx, sy;
  MAX_SPEED = 2.3; 

  constructor(p)
  {
    x = p.x;
    y = p.y;
    sx = random(-MAX_SPEED, MAX_SPEED);
    sy = random(-MAX_SPEED, MAX_SPEED);
  }

  function update()
  {
    x += sx;
    if (x < 0)
    {
      x = 0;
      sx *= -1;
    } else if (x > width)
    {
      x = width;
      sx *= -1;
    }

    y += sy;
    if (y < 0)
    {
      y = 0;
      sy *= -1;
    } else if (y > height)
    {
      y = height;
      sy *= -1;
    }
  }

  get()
  {
    return new PVector(x, y);
  }
}

